#!/usr/bin/env python3
"""Tests for the color, shortcut and hint guards in scripts/check.sh: python3 scripts/test_guards.py."""
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest

ROOT = Path(__file__).resolve().parent.parent
GREP = shutil.which('grep')
INVENTORY = '''# Interface text in keystone-agent, keystone-core, keystone-desktop and keystone-ui, by file.
# Generated by scripts/ui-strings.py. Run it after changing interface text and review the diff.

crates/keystone-agent/src/lib.rs
\tCtrl+Shift+H

crates/keystone-desktop/src/main.rs
\tNew session

crates/keystone-ui/src/kbd.rs
\tCtrl
\tCtrl N
'''
THEME = '''pub fn accent() -> Hsla {
    hsla(0.6, 0.5, 0.5, 1.0)
}
pub const PANEL: Rgba = Rgba { r: 0.1, g: 0.1, b: 0.1, a: 1.0 };
pub fn border() -> Hsla { rgb(0x223344).into() }
'''
COLOR = '''impl From<Color> for Hsla {
    fn from(color: Color) -> Hsla {
        theme::accent()
    }
}
'''
MAIN = '''fn bind(cx: &mut App) {
    cx.bind_keys([
        KeyBinding::new("ctrl-tab", NextTab, None),
        KeyBinding::new("ctrl-shift-tab", PreviousTab, None),
        KeyBinding::new("secondary-n", NewSession, None),
    ]);
}
'''


class CheckScriptGuardsTest(unittest.TestCase):
    def setUp(self):
        self.repo = Path(tempfile.mkdtemp())
        self.addCleanup(self.remove_repo)
        shutil.copytree(ROOT / 'scripts', self.repo / 'scripts')
        for stub in ('test_guards.py', 'test_ui_strings.py', 'ui-strings.py', 'case-insensitive-tests.sh'):
            (self.repo / 'scripts' / stub).write_text('')
        self.bin = self.repo / 'bin'
        self.bin.mkdir()
        self.shim('cargo', 'exit 0')
        self.write('docs/ui-strings.txt', INVENTORY)
        self.write('crates/keystone-ui/src/theme.rs', THEME)
        self.write('crates/keystone-ui/src/color.rs', COLOR)
        self.write('crates/keystone-desktop/src/main.rs', MAIN)

    def remove_repo(self):
        for folder, dirs, _ in os.walk(self.repo):
            for name in dirs:
                os.chmod(os.path.join(folder, name), 0o700)
        shutil.rmtree(self.repo)

    def write(self, path, text):
        (self.repo / path).parent.mkdir(parents=True, exist_ok=True)
        (self.repo / path).write_text(text)

    def shim(self, name, body):
        (self.bin / name).write_text(f'#!/bin/sh\n{body}\n')
        (self.bin / name).chmod(0o755)

    def check(self):
        env = {**os.environ, 'PATH': f'{self.bin}{os.pathsep}{os.environ["PATH"]}'}
        return subprocess.run(['bash', 'scripts/check.sh', '--unmeasured', 'core'], cwd=self.repo, env=env,
                              capture_output=True, text=True, timeout=60)

    def assert_passes(self):
        run = self.check()
        self.assertEqual(run.returncode, 0, run.stdout + run.stderr)

    def assert_fails(self, *evidence):
        run = self.check()
        self.assertNotEqual(run.returncode, 0, run.stdout + run.stderr)
        for text in evidence:
            self.assertIn(text, run.stdout + run.stderr)
        return run

    def test_theme_colors_color_signatures_tab_bindings_and_exempt_hints_pass(self):
        self.assert_passes()

    def test_color_constructor_outside_the_theme_fails(self):
        self.write('crates/keystone-desktop/src/panel.rs', 'fn bg() {\n    div().bg(rgb(0x112233))\n}\n')
        self.assert_fails('crates/keystone-desktop/src/panel.rs:2:')

    def test_unicode_identifier_is_not_a_color_constructor(self):
        for prefix in ('é', 'e\u0301', '\u203f'):
            with self.subTest(prefix=prefix):
                self.write('crates/keystone-desktop/src/panel.rs', f'fn custom() {{ {prefix}rgb(1); }}\n')
                self.assert_passes()

    def test_ctrl_tab_with_unicode_suffix_is_not_exempt(self):
        for suffix in ('é', '\u0301', '\u203f'):
            with self.subTest(suffix=suffix):
                self.write('crates/keystone-desktop/src/keys.rs', f'KeyBinding::new("ctrl-tab{suffix}", Palette, None);\n')
                self.assert_fails('crates/keystone-desktop/src/keys.rs:1:')

    def test_symlinked_rust_files_are_not_scanned(self):
        self.write('outside.rs', 'rgb(0x112233)\n')
        (self.repo / 'crates/keystone-desktop/src/linked.rs').symlink_to(self.repo / 'outside.rs')
        self.assert_passes()

    def test_color_struct_literal_outside_the_theme_fails(self):
        self.write('crates/keystone-desktop/src/panel.rs', 'let c = Hsla { h: 0.0, s: 0.0, l: 0.0, a: 1.0 };\n')
        self.assert_fails('crates/keystone-desktop/src/panel.rs:1:')

    def test_ctrl_binding_fails(self):
        self.write('crates/keystone-desktop/src/keys.rs', 'KeyBinding::new("ctrl-k", Palette, None);\n')
        self.assert_fails('crates/keystone-desktop/src/keys.rs:1:')

    def test_prefixed_ctrl_shift_binding_fails(self):
        self.write('crates/keystone-desktop/src/keys.rs', '\nKeyBinding::new("alt-ctrl-shift-k", Palette, None);\n')
        self.assert_fails('crates/keystone-desktop/src/keys.rs:2:')

    def test_handwritten_ctrl_hints_fail(self):
        for hint in ('Press Ctrl+K', 'Ctrl K opens the palette'):
            with self.subTest(hint=hint):
                self.write('docs/ui-strings.txt', INVENTORY + f'\ncrates/keystone-desktop/src/palette.rs\n\t{hint}\n')
                self.assert_fails(f'crates/keystone-desktop/src/palette.rs: \t{hint}')

    def without_grep_p_or_awk(self):
        self.shim('grep', f'''for a; do case $a in -*P*) echo "grep: invalid option -- 'P'" >&2; exit 2;; esac; done
exec {GREP} "$@"''')
        self.shim('awk', 'echo "awk: syntax error" >&2; exit 2')

    def test_clean_tree_passes_without_grep_p_or_awk(self):
        self.without_grep_p_or_awk()
        self.assert_passes()

    def test_color_fails_without_grep_p_or_awk(self):
        self.without_grep_p_or_awk()
        self.write('crates/keystone-desktop/src/panel.rs', 'div().bg(rgb(0x112233))\n')
        self.assert_fails('crates/keystone-desktop/src/panel.rs:1:')

    def test_ctrl_binding_fails_without_grep_p_or_awk(self):
        self.without_grep_p_or_awk()
        self.write('crates/keystone-desktop/src/keys.rs', 'KeyBinding::new("ctrl-k", Palette, None);\n')
        self.assert_fails('crates/keystone-desktop/src/keys.rs:1:')

    def test_ctrl_hint_fails_without_grep_p_or_awk(self):
        self.without_grep_p_or_awk()
        self.write('docs/ui-strings.txt', INVENTORY + '\ncrates/keystone-desktop/src/palette.rs\n\tPress Ctrl+K\n')
        self.assert_fails('crates/keystone-desktop/src/palette.rs: \tPress Ctrl+K')

    def test_a_failing_guard_fails_the_check(self):
        (self.repo / 'scripts/guards.py').write_text('import sys\nsys.exit(2)\n')
        self.assert_fails()

    def test_a_missing_guard_fails_the_check(self):
        (self.repo / 'scripts/guards.py').unlink(missing_ok=True)
        self.assert_fails()

    def test_missing_sources_fail(self):
        shutil.rmtree(self.repo / 'crates')
        self.assert_fails('No such file or directory', 'crates')

    def test_sources_without_rust_files_fail(self):
        shutil.rmtree(self.repo / 'crates')
        self.write('crates/README.md', 'No Rust here.\n')
        self.assert_fails('no Rust files under crates')

    def test_missing_inventory_fails(self):
        (self.repo / 'docs/ui-strings.txt').unlink()
        self.assert_fails('docs/ui-strings.txt')

    @unittest.skipIf(os.geteuid() == 0, 'root reads unreadable files')
    def test_unreadable_folder_fails(self):
        (self.repo / 'crates/keystone-desktop/src/locked').mkdir(mode=0)
        self.assert_fails('crates/keystone-desktop/src/locked')

    @unittest.skipIf(os.geteuid() == 0, 'root reads unreadable files')
    def test_unreadable_source_fails(self):
        (self.repo / 'crates/keystone-desktop/src/main.rs').chmod(0)
        self.assert_fails('crates/keystone-desktop/src/main.rs')

    @unittest.skipIf(os.geteuid() == 0, 'root reads unreadable files')
    def test_unreadable_inventory_fails(self):
        (self.repo / 'docs/ui-strings.txt').chmod(0)
        self.assert_fails('docs/ui-strings.txt')

    def test_source_that_is_not_utf8_is_still_checked(self):
        (self.repo / 'crates/keystone-desktop/src/panel.rs').write_bytes(b'// \xff\xfe\ndiv().bg(rgb(0x112233))\n')
        self.assert_fails('crates/keystone-desktop/src/panel.rs:2:')


if __name__ == '__main__':
    unittest.main()
